function admitDiscord(raw, headers, settings, crypto, URL, now) {
  const fail = (status, error) => ({ accepted: false, status, reply: { error } });
  const stamp = headers?.["x-signature-timestamp"],
    hex = headers?.["x-signature-ed25519"];
  if (
    !Buffer.isBuffer(raw) ||
    raw.length === 0 ||
    raw.length > 65536 ||
    !/^application\/json(?:\s*;|$)/i.test(headers?.["content-type"] ?? "") ||
    typeof stamp !== "string" ||
    !/^\d{10}$/.test(stamp) ||
    Math.abs(now - Number(stamp)) > 300 ||
    typeof hex !== "string" ||
    !/^[0-9a-f]{128}$/i.test(hex) ||
    typeof settings.publicKey !== "string" ||
    !/^[0-9a-f]{64}$/i.test(settings.publicKey)
  ) {
    return fail(401, "Invalid Discord signature.");
  }
  const spki = Buffer.from("302a300506032b6570032100" + settings.publicKey, "hex");
  const key = crypto.createPublicKey({ key: spki, format: "der", type: "spki" });
  if (
    !crypto.verify(
      null,
      Buffer.concat([Buffer.from(stamp, "ascii"), raw]),
      key,
      Buffer.from(hex, "hex"),
    )
  ) {
    return fail(401, "Invalid Discord signature.");
  }
  let body;
  try {
    body = JSON.parse(raw.toString("utf8"));
  } catch {
    return fail(400, "Invalid Discord interaction body.");
  }
  const snowflake = (value) => typeof value === "string" && /^\d{17,20}$/.test(value);
  if (
    !snowflake(settings.applicationId) ||
    (body?.type === 1 &&
      body.application_id !== undefined &&
      body.application_id !== settings.applicationId)
  ) {
    return fail(403, "Discord application is not configured.");
  }
  if (body?.type === 1) return { accepted: false, status: 200, reply: { type: 1 } };
  if (
    body?.type !== 2 ||
    body.application_id !== settings.applicationId ||
    !snowflake(body.id) ||
    !snowflake(settings.guildId) ||
    body.guild_id !== settings.guildId ||
    body.data?.name !== settings.command ||
    !/^[A-Za-z0-9_-]{16,512}$/.test(body.token ?? "")
  ) {
    return fail(403, "Command is not authorized for this application and server.");
  }
  const explain = (content) => ({
    accepted: false,
    status: 200,
    reply: { type: 4, data: { content, flags: 64 } },
  });
  const option = body.data.options?.[0];
  if (!/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(settings.dataSourceId)) {
    return explain("The Notion data source has not been configured.");
  }
  if (
    option?.name !== "url" ||
    option.type !== 3 ||
    typeof option.value !== "string" ||
    option.value.length > 2000
  ) {
    return explain("Enter a URL on an approved public website.");
  }
  let url;
  try {
    const value = option.value.trim();
    url = new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(value) ? value : "https://" + value);
  } catch {
    return explain("Enter a URL on an approved public website.");
  }
  if (
    url.protocol !== "https:" ||
    url.username ||
    url.password ||
    url.port ||
    !settings.allowedHosts.includes(url.hostname) ||
    !/^(?:[a-z0-9-]+\.)+[a-z][a-z0-9-]+$/i.test(url.hostname)
  ) {
    return explain("Enter a URL on an approved public website.");
  }
  url.hash = "";
  if (url.href.length > 2000) return explain("Enter a shorter URL.");
  return {
    accepted: true,
    url: url.href,
    dataSourceId: settings.dataSourceId,
    replyUrl:
      "https://discord.com/api/v10/webhooks/" +
      settings.applicationId +
      "/" +
      encodeURIComponent(body.token) +
      "/messages/@original",
  };
}
const settings = {
  publicKey: "YOUR_DISCORD_PUBLIC_KEY",
  applicationId: "YOUR_DISCORD_APPLICATION_ID",
  guildId: "YOUR_DISCORD_SERVER_ID",
  command: "save-link",
  allowedHosts: [],
  dataSourceId: "YOUR_NOTION_DATA_SOURCE_ID",
};
const crypto = require("crypto");
const { URL } = require("url");
let raw = null;
try {
  raw = Buffer.from(await helpers.getBinaryDataBuffer(0, "data"));
} catch {}
return {
  json: admitDiscord(raw, $json.headers, settings, crypto, URL, Math.floor(Date.now() / 1000)),
};

const { statusCode, headers, data } = $json;
const type = headers?.["content-type"] ?? "";
const html =
  statusCode === 200 &&
  /^text\/html(?:\s*;|$)/i.test(type) &&
  typeof data === "string" &&
  data.length <= 1000000
    ? data
    : "";
return { json: { html } };

function bookmark(data, rawTitle) {
  const title = typeof rawTitle === "string" ? rawTitle.trim() : "";
  if (!title || title.length > 2000)
    return {
      create: false,
      message: "Could not read an HTML title from that URL. No bookmark was added.",
    };
  return {
    create: true,
    title,
    body: {
      parent: { type: "data_source_id", data_source_id: data.dataSourceId },
      properties: {
        Name: { type: "title", title: [{ type: "text", text: { content: title } }] },
        Link: { type: "url", url: data.url },
      },
    },
  };
}
return { json: bookmark($("Verify Discord and approve the URL").first().json, $json.title) };

function confirmedBookmark(data, bookmark, status, page) {
  const normalize = (value) =>
    typeof value === "string" ? value.toLowerCase().replaceAll("-", "") : "";
  const title = page?.properties?.Name?.title;
  const actualTitle = Array.isArray(title)
    ? title.map((part) => part?.plain_text ?? part?.text?.content ?? "").join("")
    : null;
  if (
    (status !== 200 && status !== 201) ||
    page?.object !== "page" ||
    typeof page.id !== "string" ||
    !page.id ||
    page.parent?.type !== "data_source_id" ||
    normalize(page.parent.data_source_id) !== normalize(data.dataSourceId) ||
    actualTitle !== bookmark.title ||
    page.properties?.Link?.url !== data.url
  ) {
    return {
      message: "Notion did not confirm the bookmark. Check the data source before trying again.",
    };
  }
  return { message: "Added Link to notion" };
}
return {
  json: confirmedBookmark(
    $("Verify Discord and approve the URL").first().json,
    $("Prepare the Notion bookmark").first().json,
    $json.statusCode,
    $json.body,
  ),
};

const { statusCode, body } = $json;
if (
  statusCode !== 200 ||
  typeof body?.id !== "string" ||
  !body.id ||
  body.content !== $("Prepare the Discord result").first().json.content
) {
  throw new Error(
    "Discord did not confirm the interaction reply. Check Notion and Discord before running the command again.",
  );
}
return { json: { replied: true } };
